export const BUNDLES = PACKS.map((pack) => {
  const image = img(pack.photo);
  return {
    isNew: false,
    bestseller: false,
    subscribable: false,
    ...pack,
    id: `pack-${pack.slug}`,
    href: `/market-packs/${pack.slug}`,
    image,
    images: [image, img(pack.photo, 1600)],
    unit: `Serves ${pack.serves}`,
    saving: pack.value - pack.price,
    savingPercent: Math.round(((pack.value - pack.price) / pack.value) * 100),
    originalPrice: pack.value,
    stock: 50,
    category: "market-packs",
    categoryLabel: "Market packs",
  };
});

export const getBundle = (slug) => BUNDLES.find((pack) => pack.slug === slug) ?? null;
